import Foundation

extension MCPToolCatalog {
    static let sshFileReads: Set<String> = ["ssh_list_files", "ssh_stat_file", "ssh_read_file"]
    static let sshFileWrites: Set<String> = ["ssh_create_directory", "ssh_move_path", "ssh_remove_path"]
    static let sshRecoveryReads: Set<String> = ["ssh_list_transfers", "ssh_inspect_transfer", "ssh_transfer_status"]
    static let sshRecoveryWrites: Set<String> = ["ssh_cleanup_transfer", "ssh_start_transfer", "ssh_cancel_transfer", "ssh_forget_transfer"]
    static let sshTrackingTools: Set<String> = ["ssh_start_transfer", "ssh_transfer_status", "ssh_cancel_transfer", "ssh_forget_transfer"]
    static let sshTransfers: Set<String> = ["ssh_upload_file", "ssh_download_file"]
    static let sshTaskReads: Set<String> = ["ssh_list_tasks", "ssh_task_status", "ssh_task_output"]
    static let sshTaskWrites: Set<String> = ["ssh_start_task", "ssh_cancel_task", "ssh_remove_task", "ssh_forget_task"]
    static let extraSSHTitles = ["ssh_start_transfer": "启动文件传输", "ssh_transfer_status": "查询传输进度与结果", "ssh_cancel_transfer": "取消文件传输", "ssh_forget_transfer": "移除已完成的传输记录", "ssh_create_directory": "创建远程目录", "ssh_move_path": "移动或重命名远程路径", "ssh_remove_path": "删除远程文件或空目录", "ssh_list_transfers": "列出待核对的传输", "ssh_inspect_transfer": "核对传输残留", "ssh_cleanup_transfer": "清理已登记传输临时文件", "ssh_forget_task": "仅移除本机任务记录", "ssh_list_files": "浏览远程目录", "ssh_stat_file": "查看远程文件信息", "ssh_read_file": "读取远程文件",
        "ssh_upload_file": "上传文件", "ssh_download_file": "下载文件", "ssh_start_task": "启动 SSH 长任务",
        "ssh_list_tasks": "列出 SSH 长任务", "ssh_task_status": "查询 SSH 任务状态", "ssh_task_output": "读取 SSH 任务输出",
        "ssh_cancel_task": "取消 SSH 长任务", "ssh_remove_task": "清理 SSH 任务记录"]
    private static let sshSelector: [String: MCPJSONValue] = ["connection_id": string("Exact saved SSH connection UUID."),
        "timeout_seconds": integer("Total SSH request timeout, 1–300 seconds, default 30; also bounded by MCP timeout.")]
    private static func ssh(_ name: String, _ description: String, _ fields: [String: MCPJSONValue], required: [String]) -> MCPToolDefinition {
        .init(name: name, description: description, properties: sshSelector.merging(fields) { _, b in b }, required: ["connection_id"] + required)
    }
    static let sshFileDefinitions: [MCPToolDefinition] = [
        ssh("ssh_list_files", "List a remote directory through SFTP. Requires the separate file-read grant. Entries use server order; changes can affect pagination. Non-UTF8 names include name_base64.", [
            "path": string("Absolute remote directory path."), "offset": integer("Entry offset, default 0, maximum 100000."),
            "max_entries": integer("1–500, default 100; also bounded by result bytes.")], required: ["path"]),
        ssh("ssh_stat_file", "Read remote file metadata through SFTP without following the final symlink. Unsupported attributes are null. Requires the separate file-read grant.", ["path": string("Absolute remote path.")], required: ["path"]),
        ssh("ssh_read_file", "Read a bounded byte window from a regular remote file through SFTP. Requires the separate file-read grant. Use base64 for binary data or UTF-8 byte boundaries.", [
            "path": string("Absolute remote file path."), "offset": integer("Byte offset, default 0."), "max_bytes": integer("1–1048576 bytes, default 16384; bounded by result budget."),
            "encoding": .object(["type": "string", "enum": .array(["utf8", "base64"])])], required: ["path"]),
        ssh("ssh_upload_file", "Stream a regular local file to an SFTP remote path. Requires the separate transfer grant and confirm_high_risk after confirming both exact paths. Default refuses overwrite. A temporary remote file is published only after successful transfer; overwrite requires server POSIX rename. Returns source SHA256. Never retry automatically.", transferFields, required: ["local_path", "remote_path"]),
        ssh("ssh_download_file", "Stream a regular remote file to a local path. Requires file-read and transfer grants, and confirm_high_risk after confirming both exact paths. Default refuses overwrite. Local temporary data is published after successful transfer. Returns SHA256. Never retry automatically.", transferFields, required: ["local_path", "remote_path"])
    ]
    static let sshManagementDefinitions: [MCPToolDefinition] = [
        ssh("ssh_create_directory", "Create one remote directory with mode 0700 through SFTP. Parent must exist. Requires the separate file-management grant and exact-path confirmation. Existing paths are never replaced. No recursive parent creation or automatic retry.", ["path": string("Exact absolute remote path."), "confirm_high_risk": .object(["type": "boolean"])], required: ["path"]),
        ssh("ssh_move_path", "Move or rename one remote path through SFTP, without overwriting any destination. Cross-filesystem moves may be unsupported. Final symlinks are moved as links. Requires file-management grant and confirmation of both exact paths. No automatic retry.", ["path": string("Exact absolute source."), "destination_path": string("Exact absolute destination, must not exist."), "confirm_high_risk": .object(["type": "boolean"])], required: ["path", "destination_path"]),
        ssh("ssh_remove_path", "Delete exactly one remote file/symlink or an empty directory via SFTP. Never recursive; final symlink deletion leaves its target untouched. Requires file-management grant and exact-path/type confirmation. Root and ambiguous dot paths are rejected. Never retry automatically.", ["path": string("Exact absolute remote path."), "kind": .object(["type": "string", "enum": .array(["file", "empty_directory"])]), "confirm_high_risk": .object(["type": "boolean"])], required: ["path", "kind"]),
        ssh("ssh_list_transfers", "List locally tracked unfinished/failed transfer records for this account. Requires its transfer grant. Records are not proof of destination state. Historical untracked temporary files are never scanned or deleted. Pagination is newest first; registry changes may affect offsets.", ["offset": integer("Record offset 0–512, default 0."), "max_records": integer("1–100, default 20; bounded by the result budget."), "include_completed": .object(["type": "boolean", "description": "Default false. Include retained completed results (pruned on new transfers after 7 days, also bounded by 512 total records)."])], required: []),
        ssh("ssh_inspect_transfer", "Inspect a known transfer's exact staging and destination metadata, returning an inspection_token. Requires transfer grant. Refuses an active transfer. Metadata cannot prove destination content or the transfer's final outcome; do not repeat the transfer automatically.", ["transfer_id": string("Exact recorded transfer UUID.")], required: ["transfer_id"]),
        ssh("ssh_cleanup_transfer", "Remove only a recorded transfer's staging file and local recovery record. Destination is never modified. Requires transfer grant, confirm_high_risk, acknowledge_outcome_unknown and a fresh inspection_token. Refuses active transfers, changed metadata, symlinks or directories. Never scans names or retries automatically.", ["transfer_id": string("Exact recorded transfer UUID."), "inspection_token": string("Token returned by ssh_inspect_transfer after reviewing both paths."), "acknowledge_outcome_unknown": .object(["type": "boolean"]), "confirm_high_risk": .object(["type": "boolean"])], required: ["transfer_id", "inspection_token"])
    ]
    static let sshTrackingDefinitions: [MCPToolDefinition] = [
        ssh("ssh_start_transfer", "Start one tracked SFTP transfer and immediately return transfer_id for ssh_transfer_status. Requires the same grants, exact-path confirmation and overwrite rules as ssh_upload_file/ssh_download_file, plus this tool enabled. The owner MCP process must remain alive. No automatic retry/resume and no remote runtime dependency. Old plugins report progress unavailable honestly.", transferFields.merging(["direction": .object(["type": "string", "enum": .array(["upload", "download"])])]) { _, b in b }, required: ["direction", "local_path", "remote_path"]),
        ssh("ssh_transfer_status", "Read actual transfer bytes/phase and retained result by exact ID, including while running or from another MCP process. Requires transfer grant; no SSH request is made. Byte completion is not publication. A missing owner without terminal result is unknown. Speed is an average as of updated_at_unix. Completed results persist across reconnects; current destination contents are not reverified.", ["transfer_id": string("Exact transfer UUID.")], required: ["transfer_id"]),
        ssh("ssh_cancel_transfer", "Request cancellation of one active known transfer. Requires transfer grant and exact-ID confirmation. Cancellation is not completion or rollback; poll status. Never retransmit automatically.", ["transfer_id": string("Exact transfer UUID."), "confirm_high_risk": .object(["type": "boolean"])], required: ["transfer_id"]),
        ssh("ssh_forget_transfer", "Remove only a completed local result record. Requires transfer grant and exact-ID confirmation. No network or destination changes. For failed/unknown transfers use inspect/cleanup after reconciliation.", ["transfer_id": string("Exact transfer UUID."), "confirm_high_risk": .object(["type": "boolean"])], required: ["transfer_id"])
    ]
    private static let transferFields: [String: MCPJSONValue] = ["local_path": string("Absolute local file path; parent must exist. Upload input cannot be a symlink or special file."),
        "remote_path": string("Absolute remote file path; parent must exist."), "overwrite": .object(["type": "boolean", "description": "Default false. Explicitly confirm replacement of the exact destination before true."]),
        "max_transfer_bytes": integer("Maximum source file size in bytes: 1–\(SSHFileRequest.supportedMaximumTransferBytes), default \(SSHFileRequest.defaultMaximumTransferBytes) (64 MiB). For larger files explicitly set this to at least the source size; maximum 1 GiB. Oversized local uploads fail before connecting. No automatic retry."), "confirm_high_risk": .object(["type": "boolean"])]
    static let sshTaskDefinitions: [MCPToolDefinition] = [
        ssh("ssh_start_task", "Start a bounded remote background task that survives MCP disconnection. Uses existing /bin/bash and standard system utilities; requires explicit execution grant and exact-command confirmation. An unknown result includes task_id: inspect it, never relaunch automatically. Output logs are capped, no PTY/input is available.", [
            "command": string("Exact remote shell command, maximum 16384 UTF-8 bytes."), "working_directory": string("Optional absolute remote working directory; default account home."),
            "task_timeout_seconds": integer("Remote task lifetime 1–86400 seconds, default 3600; independent of this RPC timeout."),
            "max_log_bytes": integer("Combined stdout/stderr retained on server, 1024–67108864; default 4194304. Excess output is drained and discarded."),
            "confirm_high_risk": .object(["type": "boolean"])], required: ["command"]),
        ssh("ssh_list_tasks", "List locally recorded tasks for this exact authorized SSH account, newest first. Does not poll remote status. Requires an execution grant; records survive MCP restart.", [:], required: []),
        ssh("ssh_task_status", "Query a known remote task state and exit code. Requires an execution grant. Missing supervisor or transport failure does not imply the command stopped. No retry of the task is safe.", taskSelector, required: ["task_id"]),
        ssh("ssh_task_output", "Read a bounded byte window of a known task's retained stdout or stderr. Requires an execution grant. Returns base64 for lossless bytes plus replacement-decoded display text. Poll next_offset; EOF is only final when task is terminal.", taskSelector.merging([
            "stream": .object(["type": "string", "enum": .array(["stdout", "stderr"])]), "offset": integer("Byte offset, default 0."),
            "max_bytes": integer("1–262144, default 16384; bounded by MCP result budget.")]) { _, b in b }, required: ["task_id"]),
        ssh("ssh_cancel_task", "Request termination of this known task via its supervisor-owned process group. Requires an execution grant and confirmation. Returns cancellation_requested; poll status for the actual outcome. Commands that escape the process group may continue.", taskSelector.merging(["confirm_high_risk": .object(["type": "boolean"])]) { _, b in b }, required: ["task_id"]),
        ssh("ssh_forget_task", "Forget only the local record of a known task after manual reconciliation. Does not cancel any process or delete remote files/logs; the command may still be running. Requires execution grant, confirmation and acknowledge_task_may_be_running=true. Use ssh_remove_task for finished tasks instead. Refuses active local task operations.", taskSelector.merging(["confirm_high_risk": .object(["type": "boolean"]), "acknowledge_task_may_be_running": .object(["type": "boolean"])]) { _, b in b }, required: ["task_id"]),
        ssh("ssh_remove_task", "Delete logs and the local record of a finished known task. Refuses active or unknown tasks. Requires execution grant and confirmation. Does not delete arbitrary paths.", taskSelector.merging(["confirm_high_risk": .object(["type": "boolean"])]) { _, b in b }, required: ["task_id"])
    ]
    private static let taskSelector = ["task_id": string("Exact task UUID returned by ssh_start_task or ssh_list_tasks.")]
}
